import os, json, functools, subprocess, http.server, socketserver
D = os.path.expanduser('~/.cache/notice-preview')

# Which page a bare slug belongs to. On the deploy that is api/subject.mjs's
# job; here we borrow the same vocabulary rather than keep a second list that
# would go stale. node evaluates notice-vocab.js exactly as the function does.
MAP = {}
def routes():
    if not MAP:
        try:
            out = subprocess.run(['node','-e',"const fs=require('fs'),vm=require('vm');const b=vm.createContext({});vm.runInContext(fs.readFileSync(process.argv[1],'utf8'),b);const V=vm.runInContext('({PLACE_ORDER,PLACE_TYPES,EVENT_TYPES,slugify})',b);const o={};V.PLACE_ORDER.forEach(x=>o[V.slugify(x)]='place.html');V.PLACE_TYPES.concat(V.EVENT_TYPES).forEach(t=>o[V.slugify(t)]='type.html');process.stdout.write(JSON.stringify(o))", os.path.join(D,'notice-vocab.js')],
                                 capture_output=True, text=True, timeout=20)
            MAP.update(json.loads(out.stdout or '{}'))
        except Exception:
            MAP['__failed__'] = 1      # try once, then stop paying for it
    return MAP

class H(http.server.SimpleHTTPRequestHandler):
    # Stand in for what vercel.json does and a static server does not:
    # cleanUrls (/about -> about.html) and the catch-all subject rewrite
    # (/anglesea -> place.html, /surfing -> type.html). Without these every
    # nav item 404s in the preview and nowhere else, which reads as a broken
    # page rather than a missing server feature.
    def translate_path(self, path):
        p = super().translate_path(path)
        if os.path.exists(p) or os.path.splitext(p)[1]:
            return p
        if os.path.exists(p + '.html'):
            return p + '.html'
        if os.path.basename(p) == 'noticeboard':      # vercel.json rewrites this
            return os.path.join(D, 'index.html')
        page = routes().get(os.path.basename(p))
        if page:
            return os.path.join(D, page)
        parent = os.path.dirname(p)        # /place/anglesea, an old link
        if os.path.exists(parent + '.html'):
            return parent + '.html'
        return p

H = functools.partial(H, directory=D)
socketserver.TCPServer.allow_reuse_address = True
socketserver.TCPServer(('127.0.0.1', int(os.environ.get('PORT', '4173'))), H).serve_forever()
